	private static Stream<CoreDatatype> typedCoreDatatypes() {
		Stream.Builder<CoreDatatype> datatypes = Stream.builder();
		for (CoreDatatype datatype : CoreDatatype.XSD.values()) {
			datatypes.add(datatype);
		}
		for (CoreDatatype datatype : CoreDatatype.RDF.values()) {
			if (datatype != CoreDatatype.RDF.LANGSTRING && datatype != CoreDatatype.RDF.DIRLANGSTRING) {
				datatypes.add(datatype);
			}
		}
		for (CoreDatatype datatype : CoreDatatype.GEO.values()) {
			datatypes.add(datatype);
		}
		return datatypes.build();
	}

	@Test
	void updatesDatatypeNamespaceIdsWhenAReusedWriterChangesNamespaceOrder() throws Exception {
		List<List<CoreDatatype>> orders = List.of(
				List.of(CoreDatatype.RDF.HTML, CoreDatatype.RDF.JSON, CoreDatatype.XSD.STRING,
						CoreDatatype.XSD.INTEGER, CoreDatatype.GEO.WKT_LITERAL, CoreDatatype.RDF.XMLLITERAL),
				List.of(CoreDatatype.GEO.WKT_LITERAL, CoreDatatype.RDF.XMLLITERAL, CoreDatatype.RDF.HTML,
						CoreDatatype.RDF.JSON, CoreDatatype.XSD.INTEGER, CoreDatatype.XSD.STRING));
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		BinaryQueryResultWriter writer = new BinaryQueryResultWriter(output);
		for (List<CoreDatatype> order : orders) {
			output.reset();
			BindingSet[] rows = new BindingSet[order.size()];
			writer.startQueryResult(ONE_COLUMN);
			for (int i = 0; i < rows.length; i++) {
				rows[i] = new ListBindingSet(ONE_COLUMN, VF.createLiteral("row-" + i, order.get(i)));
				writer.handleSolution(rows[i]);
			}
			writer.endQueryResult();
			byte[] expected = expectedStream(ONE_COLUMN, out -> {
				Map<String, Integer> namespaces = new HashMap<>();
				for (int i = 0; i < order.size(); i++) {
					IRI datatype = order.get(i).getIri();
					Integer namespaceId = namespaces.get(datatype.getNamespace());
					if (namespaceId == null) {
						namespaceId = namespaces.size();
						namespaces.put(datatype.getNamespace(), namespaceId);
						writeNamespace(out, namespaceId, datatype.getNamespace());
					}
					writeTypedLiteral(out, "row-" + i, namespaceId, datatype.getLocalName());
				}
			});

			assertArrayEquals(expected, output.toByteArray());
			assertRoundTrip(output.toByteArray(), rows);
		}
	}

	@Test
	void interleavedWritersKeepTheirDatatypeNamespaceIdsIndependent() throws Exception {
		ByteArrayOutputStream firstOutput = new ByteArrayOutputStream();
		ByteArrayOutputStream secondOutput = new ByteArrayOutputStream();
		BinaryQueryResultWriter firstWriter = new BinaryQueryResultWriter(firstOutput);
		BinaryQueryResultWriter secondWriter = new BinaryQueryResultWriter(secondOutput);
		String precedingNamespace = "http://example.org/preceding/";
		BindingSet preceding = new ListBindingSet(ONE_COLUMN, VF.createIRI(precedingNamespace, "item"));
		BindingSet first = new ListBindingSet(ONE_COLUMN, VF.createLiteral("first"));
		BindingSet second = new ListBindingSet(ONE_COLUMN, VF.createLiteral("second"));
		firstWriter.startQueryResult(ONE_COLUMN);
		firstWriter.handleSolution(preceding);
		firstWriter.handleSolution(first);
		secondWriter.startQueryResult(ONE_COLUMN);
		secondWriter.handleSolution(first);
		firstWriter.handleSolution(second);
		firstWriter.endQueryResult();
		secondWriter.handleSolution(second);
		secondWriter.endQueryResult();
		byte[] expectedFirst = expectedStream(ONE_COLUMN, out -> {
			writeNamespace(out, 0, precedingNamespace);
			writeQName(out, 0, "item");
			writeNamespace(out, 1, XSD_NAMESPACE);
			writeTypedLiteral(out, "first", 1, "string");
			writeTypedLiteral(out, "second", 1, "string");
		});
		byte[] expectedSecond = expectedStream(ONE_COLUMN, out -> {
			writeNamespace(out, 0, XSD_NAMESPACE);
			writeTypedLiteral(out, "first", 0, "string");
			writeTypedLiteral(out, "second", 0, "string");
		});

		assertArrayEquals(expectedFirst, firstOutput.toByteArray());
		assertArrayEquals(expectedSecond, secondOutput.toByteArray());
		assertRoundTrip(firstOutput.toByteArray(), preceding, first, second);
		assertRoundTrip(secondOutput.toByteArray(), first, second);
	}

