		assertEquals(namespace, unusual.getDatatype().getNamespace());
		BindingSet first = new ListBindingSet(ONE_COLUMN, VF.createLiteral("first"));
		BindingSet second = new ListBindingSet(ONE_COLUMN, unusual);
		BindingSet third = new ListBindingSet(ONE_COLUMN, VF.createLiteral("third"));
