	@Test
	void preservesMoreThanOneBufferOfMarkersAfterAChangedValue() throws Exception {
		int columns = 4111;
		List<String> names = new ArrayList<>(columns);
		MapBindingSet first = new MapBindingSet(columns);
		MapBindingSet second = new MapBindingSet(columns);
		Value repeated = VF.createBNode("same");
		for (int column = 0; column < columns; column++) {
			String name = "column-" + column;
			names.add(name);
			first.setBinding(name, repeated);
			if (column == 0) {
				second.setBinding(name, VF.createBNode("changed"));
			} else if ((column & 1) == 0) {
				second.setBinding(name, repeated);
			}
		}
		BindingSet[] rows = { first, EmptyBindingSet.getInstance(), second };
		byte[] actual = serialize(names, rows);
		byte[] expected = expectedStream(names, out -> {
			for (int column = 0; column < columns; column++) {
				writeBNode(out, "same");
			}
			out.writeByte(9);
			writeBNode(out, "changed");
			for (int column = 1; column < columns; column++) {
				out.writeByte((column & 1) == 0 ? 1 : 0);
			}
		});

		assertArrayEquals(expected, actual);
		assertRoundTrip(actual, rows);
	}

