	@TestFactory
	Stream<DynamicTest> preservesCompletedColumnOutputWhenALaterValueFails() {
		return Stream.of("malformed", "runtime", "error")
				.map(kind -> DynamicTest.dynamicTest(kind, () -> {
					List<String> names = List.of("first", "failing");
					ByteArrayOutputStream output = new ByteArrayOutputStream();
					BinaryQueryResultWriter writer = new BinaryQueryResultWriter(output);
					RuntimeException getterFailure = new IllegalStateException("Injected getter failure");
					Error getterError = new AssertionError("Injected getter error");
					Literal later = new SimpleLiteral("\ud800") {
						@Override
						public String getLabel() {
							if (kind.equals("runtime")) {
								throw getterFailure;
							}
							if (kind.equals("error")) {
								throw getterError;
							}
							return super.getLabel();
						}
					};
					writer.startQueryResult(names);
					writer.handleSolution(primingRow(names));
					BindingSet row = new ListBindingSet(names, VF.createLiteral("completed"), later);
					if (kind.equals("malformed")) {
						assertMalformedInput(assertThrows(TupleQueryResultHandlerException.class,
								() -> writer.handleSolution(row)).getCause());
					} else if (kind.equals("runtime")) {
						assertSame(getterFailure, assertThrows(IllegalStateException.class,
								() -> writer.handleSolution(row)));
					} else {
						assertSame(getterError, assertThrows(AssertionError.class,
								() -> writer.handleSolution(row)));
					}
					byte[] expected = expectedStream(names, out -> {
						writePrimingRow(out, names.size());
						writeNamespace(out, 0, XSD_NAMESPACE);
						writeTypedLiteral(out, "completed", 0, "string");
					});

					assertArrayEquals(Arrays.copyOf(expected, expected.length - 1), output.toByteArray());
					output.reset();
					writer.error(QueryErrorType.QUERY_EVALUATION_ERROR, "terminal");
					ByteArrayOutputStream error = new ByteArrayOutputStream();
					DataOutputStream errorOut = new DataOutputStream(error);
					errorOut.write(new byte[] { 126, 2 });
					writeString(errorOut, "terminal");
					assertArrayEquals(error.toByteArray(), output.toByteArray());
				}));
	}

	@Test
	void propagatesFinalRowWriteFailureWithoutRetryOrLeakingBytesIntoAnError() throws Exception {
		List<String> names = List.of("first", "last");
		ControlledOutput output = new ControlledOutput();
		BinaryQueryResultWriter writer = new BinaryQueryResultWriter(output);
		Literal last = new SimpleLiteral("last") {
			@Override
			public String getLabel() {
				// Earlier small records are already written or queued. The next target write must fail once.
				output.failWrites = true;
				return super.getLabel();
			}
		};
		writer.startQueryResult(names);
		writer.handleSolution(primingRow(names));
		TupleQueryResultHandlerException failure = assertThrows(TupleQueryResultHandlerException.class,
				() -> writer.handleSolution(new ListBindingSet(names, VF.createLiteral("first"), last)));

		assertSame(output.writeFailure, failure.getCause());
		assertEquals(1, output.failedWrites, "A failed target write must not be retried during cleanup");
		assertEquals(0, output.closes);
		output.failWrites = false;
		output.bytes.reset();
		writer.error(QueryErrorType.QUERY_EVALUATION_ERROR, "terminal");
		ByteArrayOutputStream expected = new ByteArrayOutputStream();
		DataOutputStream out = new DataOutputStream(expected);
		out.write(new byte[] { 126, 2 });
		writeString(out, "terminal");

		assertArrayEquals(expected.toByteArray(), output.bytes.toByteArray());
		assertEquals(1, output.failedWrites);
	}

	@TestFactory
	Stream<DynamicTest> preservesOrderForReentrantOutputStreamWritesAndFlushes() {
		return Stream.of(false, true)
				.map(flushBeforeWrite -> DynamicTest.dynamicTest(
						flushBeforeWrite ? "flush then write" : "write before flush", () -> {
							List<String> names = List.of("first", "reentrant", "last");
							ControlledOutput output = new ControlledOutput();
							BinaryQueryResultWriter writer = new BinaryQueryResultWriter(output);
							String injectedNamespace = "urn:externally-written:";
							ByteArrayOutputStream injected = new ByteArrayOutputStream();
							writeNamespace(new DataOutputStream(injected), 1, injectedNamespace);
							byte[] injectedBytes = injected.toByteArray();
							byte[] prefix = expectedStream(names, out -> {
								writePrimingRow(out, names.size());
								writeNamespace(out, 0, XSD_NAMESPACE);
								writeTypedLiteral(out, "first", 0, "string");
							});
							Literal reentrant = new SimpleLiteral("second") {
								@Override
								public String getLabel() {
									OutputStream view = writer.getOutputStream();
									assertDoesNotThrow(() -> {
										if (flushBeforeWrite) {
											view.flush();
											assertArrayEquals(Arrays.copyOf(prefix, prefix.length - 1),
													output.bytes.toByteArray());
										}
										view.write(injectedBytes[0]);
										view.write(injectedBytes, 1, 4);
										view.write(Arrays.copyOfRange(injectedBytes, 5, injectedBytes.length));
										view.flush();
									});
									return super.getLabel();
								}
							};
							writer.startQueryResult(names);
							writer.handleSolution(primingRow(names));
							writer.handleSolution(new ListBindingSet(names, VF.createLiteral("first"), reentrant,
									VF.createBNode("last")));
							byte[] expected = expectedStream(names, out -> {
								writePrimingRow(out, names.size());
								writeNamespace(out, 0, XSD_NAMESPACE);
								writeTypedLiteral(out, "first", 0, "string");
								writeNamespace(out, 1, injectedNamespace);
								writeTypedLiteral(out, "second", 0, "string");
								writeBNode(out, "last");
							});

							assertArrayEquals(Arrays.copyOf(expected, expected.length - 1), output.bytes.toByteArray());
							assertEquals(flushBeforeWrite ? 2 : 1, output.flushes);
							writer.endQueryResult();
							assertArrayEquals(expected, output.bytes.toByteArray());
							assertEquals(flushBeforeWrite ? 3 : 2, output.flushes);
							assertEquals(0, output.closes);
						}));
	}

